  senses:[
    { vi:'có thể (năng lực)', ex:['I can swim.','Tôi biết bơi.'] },
    { vi:'được phép (xin phép, cho phép)', ex:['Can I come in?','Tôi vào được không?'] },
    { vi:'có khả năng xảy ra', ex:['It can be very cold here.','Ở đây có thể rất lạnh.'] }
  ],
